css:
.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px 16px;
  padding: 12px;
}

.card {
  display: grid;
  grid-row: span 3;
  grid-template-rows: subgrid;
  padding: 12px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

.card h3,
.card p {
  margin: 0;
}

.buy {
  justify-self: start;
  padding: 6px 12px;
  border: 0;
  border-radius: 4px;
  background: #f97316;
  color: #fff;
}
